class Solution {
public:
    long long repairCars(std::vector<int>& ranks, int cars) {
        long long min_r = *std::min_element(ranks.begin(), ranks.end());
        long long low = 1, high = min_r * (long long)cars * cars;
        while (low < high) {
            long long mid = low + (high - low) / 2;
            long long total = 0;
            for (int r : ranks) {
                total += (long long)std::sqrt(mid / r);
            }
            if (total >= cars) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
};

class Solution {
    public long repairCars(int[] ranks, int cars) {
        long minR = ranks[0];
        for (int r : ranks) minR = Math.min(minR, r);
        long low = 1, high = minR * (long) cars * cars;
        while (low < high) {
            long mid = low + (high - low) / 2;
            long total = 0;
            for (int r : ranks) {
                total += (long) Math.sqrt((double) mid / r);
            }
            if (total >= cars) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

var repairCars = function(ranks, cars) {
    let minR = BigInt(Math.min(...ranks));
    const bigCars = BigInt(cars);
    let low = 1n, high = minR * bigCars * bigCars;
    while (low < high) {
        const mid = (low + high) / 2n;
        let total = 0n;
        for (const r of ranks) {
            const val = mid / BigInt(r);
            // BigInt integer square root
            let s = 0n;
            if (val > 0n) {
                let x0 = val / 2n;
                if (x0 !== 0n) {
                    let x1 = (x0 + val / x0) / 2n;
                    while (x1 < x0) {
                        x0 = x1;
                        x1 = (x0 + val / x0) / 2n;
                    }
                    s = x0;
                } else {
                    s = 1n;
                }
            }
            total += s;
        }
        if (total >= bigCars) {
            high = mid;
        } else {
            low = mid + 1n;
        }
    }
    return Number(low);
};
